-- Model: lnk_pcoiburden_placement__pcoi_burden_hkey_curr
-- Description: Current active relationship for LNK_PCOIBURDEN_PLACEMENT using ROW_NUMBER()
-- Generated by: bv pipeline generate transform
-- Link Type: RELATIONSHIP_BASED_LINK

WITH RANKED_RELATIONSHIPS AS (
SELECT
    l.LNK_PCOIBURDEN_PLACEMENT_HKEY AS LNK_PCOIBURDEN_PLACEMENT_HKEY,
    l.PCOI_BURDEN_HKEY AS PCOI_BURDEN_HKEY,
    l.PLACEMENT_HKEY AS PLACEMENT_HKEY,

    -- TODO: use generated tag instead of well-known name _CURRENT_ACTIVE_TIMESTAMP
    ls._CURRENT_ACTIVE_TIMESTAMP AS _CURRENT_RELATIONSHIP_TIMESTAMP, -- was ls.DATELASTSYNC

    ROW_NUMBER() OVER (
        PARTITION BY l.PCOI_BURDEN_HKEY -- parent hub hk
        ORDER BY ls._CURRENT_ACTIVE_TIMESTAMP DESC -- TODO: as above. Was ls.DATELASTSYNC
    ) AS row_num

FROM {{ source('eli_dv_rv', 'lnk_pcoiburden_placement') }} l
INNER JOIN {{ ref('lks_bh1_pcoiburden_placement_curr') }} ls
    ON l.LNK_PCOIBURDEN_PLACEMENT_HKEY = ls.LNK_PCOIBURDEN_PLACEMENT_HKEY
)

SELECT * EXCLUDE (row_num)
FROM RANKED_RELATIONSHIPS
WHERE row_num = 1
